#include <iostream>
#include <vector>

/* First index i such that v[i] >= target, or v.size() if none. */
std::size_t lowerBound(const std::vector<int>& v, int target)
{
    std::size_t lo{ 0 };
    std::size_t hi{ v.size() };
    while (lo < hi)
    {
        std::size_t mid{ lo + (hi - lo) / 2 };
        if (v[mid] < target) lo = mid + 1;
        else                 hi = mid;
    }
    return lo;
}

/* First index i such that v[i] > target, or v.size() if none. */
std::size_t upperBound(const std::vector<int>& v, int target)
{
    std::size_t lo{ 0 };
    std::size_t hi{ v.size() };
    while (lo < hi)
    {
        std::size_t mid{ lo + (hi - lo) / 2 };
        if (v[mid] <= target) lo = mid + 1;
        else                  hi = mid;
    }
    return lo;
}

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    std::vector<int> v;
    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
    }

    int q{};
    std::cin >> q;
    for (int i = 0; i < q; ++i)
    {
        int target{};
        std::cin >> target;
        std::size_t lb{ lowerBound(v, target) };
        std::size_t ub{ upperBound(v, target) };
        std::cout << target << " lower " << lb
                  << " upper " << ub
                  << " count " << (ub - lb) << "\n";
    }

    return 0;
}

