import sys

def lower_bound(v, target):
    lo, hi = 0, len(v)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if v[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upper_bound(v, target):
    lo, hi = 0, len(v)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if v[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    n = int(data[pos]); pos += 1
    v = [int(data[pos + i]) for i in range(n)]; pos += n
    q = int(data[pos]); pos += 1
    out = []
    for _ in range(q):
        target = int(data[pos]); pos += 1
        lb = lower_bound(v, target)
        ub = upper_bound(v, target)
        out.append("%d lower %d upper %d count %d" % (target, lb, ub, ub - lb))
    print("\n".join(out))

main()
